(async () => {
 const wait = async (find) => { const until=Date.now()+45000; while(Date.now()<until){const v=find();if(v)return v;await new Promise(r=>setTimeout(r,100));}throw new Error('long-session control unavailable'); };
 window.__longSessionWait=wait;
 const toggle=await wait(()=>document.querySelector('[data-testid="workspace-toggle-view"]'));
 window.__longSessionInitialMode=toggle.dataset.viewMode;
 const title=document.querySelector('[data-testid="workspace-sidebar-active-title"]');
 window.__longSessionInitialTitle=title?.getAttribute('title');
 if(!window.__longSessionInitialTitle?.includes('Investigate prompt-manager heartbeat')){
  if(!document.querySelector('[data-testid^="sidebar-session-"]'))document.querySelector('[data-testid="workspace-sidebar-toggle"]')?.click();
  const target=await wait(()=>[...document.querySelectorAll('[data-testid^="sidebar-session-"]')].find(e=>e.textContent.includes('Investigate prompt-manager heartbeat')));
  target.click();await new Promise(r=>setTimeout(r,300));
 }
 const selectedToggle=document.querySelector('[data-testid="workspace-toggle-view"]');
 if(selectedToggle.dataset.viewMode!=='messages')selectedToggle.click();
 const scroller=await wait(()=>document.querySelector('[data-testid="messages-scroll"]'));
 await wait(()=>scroller.querySelector('[data-event-id]'));
 await new Promise(r=>setTimeout(r,1000));
 await new Promise(r=>setTimeout(r,5000));
 const resources=performance.getEntriesByType('resource');
 window.__sessionStartup={conversationLoads:resources.filter(r=>r.name.includes('ConversationService/Get')).map(r=>({start:r.startTime,duration:r.duration})),scriptBytes:resources.filter(r=>r.initiatorType==='script').reduce((n,r)=>n+r.decodedBodySize,0),readyAt:performance.now()};
 return {session:document.querySelector('[data-testid="workspace-sidebar-active-title"]')?.getAttribute('title'),count:document.querySelector('[data-testid="messages-search-field"]')?.dataset.count,viewport:[innerWidth,innerHeight],startup:window.__sessionStartup};
})()
